__NUXT_JSONP__("/de/westwood", (function(a,b){return {data:[{details:{slug:a,pageTitle:"Westwood Campus | Mentor Language Institute",pageDescription:b,title:"Westwood Campus",image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-campus.jpg",yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FfsCjSV4E_l0",subtitle:[b,"Westwood ist bekannt als Heimat der UCLA. Der Westwood Campus befindet sich an der Ecke des Wilshire Blvd und des Westwood Blvd. Er ist nur 1 Gehminute von der Hauptbuslinie am Wilshire Blvd und dem Westwood Blvd entfernt.","Es ist eine sehr amüsante und populäre Gegend für Studenten und auch für Geschäftsleute, da es viele Geschäfte, Restaurants und sichere Plätze zum Verweilen gibt."],landmark:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fsanta-monica.jpg",title:"20 Minuten nach Santa Monica mit dem Bus"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fbeverly-hills.jpg",title:"10 Minuten nach Beverly Hills mit dem Bus"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Flos-angeles-skyline.jpg",title:"60 Minuten nach Downtown LA mit dem Bus"}],gallery:{title:"Fotogallerie des Westwood Campus",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002F10880-building.jpg",title:"Es befindet sich im Erdgeschoss des Gebäudes.",subtitle:"Du musst keinen Aufzug benutzen, um in die Klasse zu kommen."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffront-desk.jpg",title:"Rezeption"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fclassroom.jpg",title:"Klassenräume"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fcomputer-room.jpg",title:"Computerraum"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fstudent-lounge.jpg",title:"Studentenlounge"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffree-space.jpg",title:"Aufenthaltsraum"}]},location:{title:"Standort",map_link:"https:\u002F\u002Fwww.google.com\u002Fmaps\u002Fembed?pb=!1m18!1m12!1m3!1d3305.4289041796537!2d-118.44512238478478!3d34.05851788060419!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2bb7e2b42fadf%3A0xad96227841e11efb!2s10880+Wilshire+Blvd%2C+Los+Angeles%2C+CA+90024!5e0!3m2!1sen!2sus!4v1513884279258"},video:[{title:"1. Wie komme ich zu MLI Westwood Campus mit dem Bus",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV2zydV7aWvA"},{title:"2. Anfahrt zum MLI Westwood Campus mit dem Auto",space:"\u003Cbr\u002F\u003E",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F5FXkkyV3DZg"}],environment:{title:"Umgebung",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fucla.jpg",title:"In Gehdistanz zur UCLA"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fhammer-museum.jpg",title:"Das Hammer Museum, das bekannteste Museum in LA, ist gleich gegenüber von unserem Campus."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-library.jpg",title:"Hinter unserem Campus befindet sich eine Bibliothek, wo du lernen kannst."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fchevron-restaurant.jpg",title:"Es gibt viele erschwingliche Restaurants."}]},accommodation:{title:"Unterkünfte",description:["Wir bieten Gastfamilien oder Studentenwohnheime als Unterkünfte an."],types:[{desc:["＜Studentenwohnheim＞\u003Cbr \u002F\u003EEs gibt 40 Zimmer im Studentenwohnheim und du kannst mit dem Bus oder zu Fuss in die Schule gehen."],yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV_eNdjw6Z1c"},{desc:["＜Gastfamilien＞"],yt_link2:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FK4DT7WEI7MY",other_desc:["Gastfamilien sind der beste Weg, um mehr über die amerikanische Kultur zu lernen und deine Möglichkeiten Englisch zu sprechen zu erhöhen.","\u003Ca href=\"\u002Fde\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E Mehr Details über die Unterkünfte\u003C\u002Fa\u003E"]}]},courses:{title:"Kurse",lists:["ESL Program","TOEFL®","IELTS™","Konversationsrogramm","TOEIC®"]},message:{title:"Nachricht vom Westwood Campus",image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-director.jpg",position:"Nachricht vom Campus - direktor",description:["Der Westwood Campus befindet sich in einer grossartigen Gegend in der Nähe der UCLA. Es gibt viele verschiedene Orte, die man besuchen kann wie zum Beispiel Kinos, Geschäfte und Museen. Unser TOEFL® Kurs ist sehr beliebt, da viele unserer Studenten später an der Universität studieren möchten. Ausserdem ist unsere Studiengebühr unglaublich preiswert. Viele Schüler von anderen Schulen wechseln zu uns ans MLI."]},dir:"\u002Fwestwood",path:"\u002Fwestwood\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:31.393Z",updatedAt:"2025-05-26T12:06:28.038Z"},lang:a}],fetch:{},mutations:void 0}}("de","Westwood ist eine lebendige und einzigartige Nachbarschaft im westlichen Teil von Los Angeles.")));